  keys=raw.keys.map((row,index)=>{exact(row,['networkId','key']);need(row.networkId===PUBLIC_PAGED_TESTNET_IDS_V1[index]&&/^[0-9a-f]{64}$/.test(row.key),'PUBLIC_KEY_ENVELOPE');const key=Buffer.from(row.key,'hex');return{key,account:publicPagedAccountFromKeyV1(row.networkId,key)};});
